def format_mistral_prompt(user_message: str, history: List[Dict[str, str]] | None = None) -> str:
    """Format prompt using tokenizer's chat template when available."""
    messages: List[Dict[str, str]] = []

    # System message
    messages.append({"role": "user", "content": f"[SYSTEM] {SYSTEM_PROMPT.strip()}"})
    messages.append({"role": "assistant", "content": "Understood. I'm SingularityDrive AI, ready to help with technical questions, security analysis, and code assistance. How can I help you?"})

    # Add conversation history
    if history:
        messages.extend(history)

    # Current user message
    messages.append({"role": "user", "content": user_message})

    # Use tokenizer's chat template if available
    if hasattr(tokenizer, "apply_chat_template"):
        return tokenizer.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True,
        )
    else:
        # Fallback: simple format without raw [INST] tags
        convo = [SYSTEM_PROMPT.strip()]
        if history:
            for turn in history:
                if turn["role"] == "user":
                    convo.append(f"\n\nUser: {turn['content']}")
                elif turn["role"] in ("assistant", "ghost"):
                    convo.append(f"\nAssistant: {turn['content']}")
        convo.append(f"\n\nUser: {user_message}\nAssistant:")
        return "".join(convo)
